 void collect(){platform::PracticeTempoEvidence p;while(provider.nextTempoEvidence(p)){last=p;packets.push_back(p);if(apply)check(provider.applyTempoEvidence(p,co),"fresh complete dynamic packet accepted by original");}
  scheduler::Fact f;while(provider.nextFact(f)){check(f.owner==state.owner,"all scheduled facts retain their actual generation");facts.push_back(f);}}
 void observe(){tempo_allocation::allocations=0;tempo_allocation::counting=true;platform::PracticePlayback::observe(&provider,state);tempo_allocation::counting=false;allocations+=tempo_allocation::allocations;collect();}
 scheduler::BlockOutcome propose(std::uint32_t frames){*buses={};tempo_allocation::allocations=0;tempo_allocation::counting=true;auto r=platform::PracticePlayback::render(&provider,state.owner,co.configuration().rate,frames,*buses);tempo_allocation::counting=false;allocations+=tempo_allocation::allocations;++blocks;return r;}
 void runTo(std::uint64_t target,std::uint32_t chunk=2048){if(packets.empty())observe();
  while(state.submittedFrames<target){const auto request=static_cast<std::uint32_t>(std::min<std::uint64_t>(chunk,target-state.submittedFrames));auto r=propose(request);
   check(r.valid&&r.submittedFrames==request,"actual provider supplies entire declared positive prefix");
   for(std::uint32_t i=0;i<r.submittedFrames;++i){if(!std::isfinite((*buses)[0][0][i])||!std::isfinite((*buses)[1][0][i])||(*buses)[0][0][i]!=(*buses)[0][1][i]||(*buses)[1][0][i]!=(*buses)[1][1][i])throw std::runtime_error("Nonfinite or asymmetric provider output");notes.push_back((*buses)[0][0][i]);clicks.push_back((*buses)[1][0][i]);}
   state.submittedFrames+=r.submittedFrames;if(r.terminal)state.state=output::State::Unresolved;observe();
  }
 }
 void finishAcross(std::uint64_t endpoint){auto r=propose(256);check(r.valid&&r.terminal&&r.submittedFrames==endpoint-state.submittedFrames&&r.submittedFrames<256,"cross-final request returns exact legitimate shorter terminal prefix");for(std::uint32_t i=0;i<r.submittedFrames;++i){notes.push_back((*buses)[0][0][i]);clicks.push_back((*buses)[1][0][i]);}state.submittedFrames+=r.submittedFrames;state.state=output::State::Unresolved;observe();}
 void finish(){if(state.state==output::State::Running){auto r=propose(256);check(r.valid&&r.terminal&&r.submittedFrames==0,"final endpoint stops before another musical sample");state.state=output::State::Unresolved;state.requestedStopNs=123456;observe();}}
 void pause(){state.state=output::State::Paused;state.requestedStopNs=123456;state.uncertainThrough=state.submittedFrames;observe();}
 platform::PracticeTempoEvidence reclaim(){practice::Progress wrong;check(!provider.reclaim(wrong),"fixed reclaim cannot consume dynamic terminal");platform::PracticeTempoEvidence p;check(provider.reclaimTempoEvidence(p)&&p.progress.terminal&&p.progress.owner==state.owner,"complete dynamic terminal fallback reclaimed");check(storage::canonical(packetValue(p))==storage::canonical(packetValue(last)),"fallback exactly matches latest complete observed packet");check(!provider.applyTempoEvidence(p,co),"duplicate terminal cannot add original credit");return p;}
 bool manual(std::uint64_t seq,int bpm){check(provider.manualTempo(state.owner,7,seq,bpm),"valid owned manual intent enqueued");observe();platform::PracticeTempoReply reply;check(provider.nextTempoReply(reply)&&reply.owner==state.owner&&reply.binding==7&&reply.sequence==seq&&reply.bpm==bpm,"manual reply preserves complete command identity");const auto accepted=reply.accepted;observe();return accepted;}
 void save(const std::filesystem::path& out,const std::string& name){A ps,fs;for(const auto& p:packets)ps.push_back(packetValue(p));for(const auto& f:facts)fs.push_back(O{{"kind",n(static_cast<int>(f.kind))},{"cycle",n(f.cycle)},{"frame",n(f.frame)},{"binding",n(f.binding)},{"source_event",n(f.sourceEvent)},{"role",n(static_cast<int>(f.role))},{"action",n(static_cast<int>(f.action))}});
  write(out/(name+"-packets.json"),storage::canonical(ps));write(out/(name+"-facts.json"),storage::canonical(fs));
  write(out/(name+"-notes.f32"),std::string(reinterpret_cast<const char*>(notes.data()),notes.size()*sizeof(float)));write(out/(name+"-clicks.f32"),std::string(reinterpret_cast<const char*>(clicks.data()),clicks.size()*sizeof(float)));
  write(out/(name+"-execution.json"),storage::canonical(O{{"blocks",n(blocks)},{"frames",n(notes.size())},{"ordinary_new_allocations",n(allocations)},{"classification","actual software render and synthetic client submission; no callback/DAC/acoustic observation"}}));check(allocations==0,"measured observe/render regions contain zero ordinary operator-new calls");
 }
