// Formula independently specified before execution; positions come only from frozen source oracle.
double expectedSample(bool pluck,double hz,std::uint64_t age,std::uint64_t length,std::uint32_t rate){if(age>=length)return 0;const double t=static_cast<double>(age)/rate;const double phase=6.283185307179586476925286766559*hz*t;double wave=std::sin(phase);if(pluck)wave=(wave+.4*std::sin(2*phase)+.2*std::sin(3*phase))/1.6*std::exp(-6*t);return wave*std::min(t/.003,1.0)*std::min((static_cast<double>(length)/rate-t)/.01,1.0);}
using EventTuple=std::tuple<int,std::uint64_t,std::uint64_t,std::uint32_t,int,int>;
void compareOracle(const Driver& d,const V& oracle){const auto rate=static_cast<std::uint32_t>(number(at(oracle,"rate")));const auto end=number(at(oracle,"terminal_frame"));check(d.notes.size()==end&&d.clicks.size()==end,"all oracle frames retained for exact PCM comparison");
 struct Voice {std::uint64_t start,end;double hz;};std::vector<Voice> voices;std::vector<std::uint64_t> pulses;std::multiset<EventTuple> expected,actual;
 for(const auto& cycle:at(oracle,"cycles").array()){const auto ci=number(at(cycle,"cycle"));std::uint32_t id=0;for(const auto& v:at(cycle,"voices").array()){++id;const auto start=number(at(v,"attack_frame")),release=number(at(v,"release_frame"));const double hz=440.0*std::pow(2.0,(static_cast<int>(number(at(v,"midi")))-69)/12.0);voices.push_back({start,release,hz});expected.emplace(0,ci,start,id,0,0);expected.emplace(0,ci,release,id,0,1);}
  for(const auto& pulse:at(cycle,"quarter_pulses").array()){const auto frame=number(at(pulse,"frame"));pulses.push_back(frame);expected.emplace(0,ci,frame,static_cast<std::uint32_t>(number(at(pulse,"q"))+1),1,0);}expected.emplace(1,ci+1,number(at(cycle,"end_frame")),0,0,0);
 }
 for(const auto& f:d.facts){actual.emplace(static_cast<int>(f.kind),f.cycle,f.frame,f.sourceEvent,static_cast<int>(f.role),static_cast<int>(f.action));check(f.binding==7,"actual source and click facts use unchanged original binding");}
 check(actual==expected,"every reference attack/release, click and cycle matches independent exact source oracle");std::size_t vi=0,pi=0;bool notes=true,clicks=true;
 for(std::uint64_t frame=0;frame<end;++frame){while(vi<voices.size()&&voices[vi].end<=frame)++vi;double value=0;if(vi<voices.size()&&voices[vi].start<=frame)value=expectedSample(true,voices[vi].hz,frame-voices[vi].start,voices[vi].end-voices[vi].start,rate)/6.0;
  while(pi+1<pulses.size()&&pulses[pi+1]<=frame)++pi;const auto pulse=static_cast<float>(expectedSample(false,1000,frame-pulses[pi],std::max(1U,rate/40),rate));notes=notes&&d.notes[static_cast<std::size_t>(frame)]==static_cast<float>(value);clicks=clicks&&d.clicks[static_cast<std::size_t>(frame)]==pulse;}
 check(notes&&clicks,"every produced reference/click float equals independently timed literal formula");check(d.last.pointCount==32&&d.last.tempo.tempo==199&&d.last.progress.completedCycles==32,"all32 applied tempos and unique completed spans retained");
 for(std::uint32_t i=0;i<32;++i){check(d.last.points[i].cycle==i&&d.last.points[i].bpm==137+2*i,"complete point array preserves every137 to199 step");check(d.co.timeline(d.co.owner()).frame(i)==number(at(at(oracle,"cycles").array()[i],"start_frame")),"control map agrees with independent exact accumulated boundary");}
 check(d.co.configuration().bpm==137&&d.co.currentTempo()==199&&d.co.activeFrames()==end,"original selected137 remains distinct from played199 and actual confirmed time");
}
